public class Ball extends Circle {

   //Attribute
   public String farbe;
   public int radius;
   public int startX = 300;
   public int startY = 200;
   public float geschwindigkeit; 
   public float richtung; 

   //Referenzattribute
   public Spiel meinSpiel;
   public Schlaeger meinSchlaeger;

   //Konstruktor
   public Ball(String _farbe, int _radius, Spiel _spiel, Schlaeger _schlaeger) 
   {
      super(startX, startY, _radius);
      farbe = _farbe;
      radius = _radius; 
      setFillColor(farbe);
      meinSpiel = _spiel;
      meinSchlaeger = _schlaeger;
   }


   //Methoden
   public void act() {

      defineDirection(richtung);
      forward(geschwindigkeit);

      if(getCenterY() > 745) {
         meinSpiel.verliereLeben();
      }

      if(getCenterY() < 5) abprallenY();
      if(getCenterX() < 5) abprallenX(); 
      if(getCenterX() > 595) abprallenX(); 
      if(collidesWith(meinSchlaeger)) abprallenY();

   }

   public void geheAufStart() 
   {
      moveTo(startX, startY);
      geschwindigkeit = 30;
      richtung = 315; 
   }

   public void abprallenX() {
      richtung = 540 - richtung;
   } 

   public void abprallenY() {
      richtung = 360 - richtung;
   } 

}

public class Spiel extends Actor {

   //Attribute
   public int punkte;
   public int leben;

   public Schlaeger meinSchlaeger;
   public Ball meinBall;
   public Text punkteText; 
   public Text lebenText; 


   //Konstruktor
   public Spiel() {
      punkte = 0;
      leben = 3; 
      meinSchlaeger = new Schlaeger("red", 80, this);
      meinBall = new Ball("green", 10, this, meinSchlaeger);
      punkteText = new Text(460, 5, 32, "Punkte: " + punkte);
      lebenText = new Text(10, 5, 32, "Leben: " + leben); 

      for (int i = 0; i < 40; i++)
      {
         new Block("blue", (i % 10) * 60, 50 + (i / 10) * 30, meinBall, this); 
      } 
      meinBall.geheAufStart();
   }

   //Methoden
   public void act()
   {
      lebenText.setText("Leben: " + leben);
      punkteText.setText("Punkte: " + punkte); 
      punkteText.moveTo(this.getWorld().getWidth() - punkteText.getWidth() - 10, 5);

      if(leben == 0) {
         Text text = new Text(60, 200, 80, "GAME OVER"); 
         text.moveTo((this.getWorld().getWidth() / 2) - text.getWidth() / 2, 200);
         SystemTools.pause(200);
         System.exit(2);
      } if(punkte >= 40) {
         Text text = new Text(60, 200, 80, "GAME WON"); 
         text.moveTo((this.getWorld().getWidth() / 2) - text.getWidth() / 2, 200);
         SystemTools.pause(200);
         System.exit(1);
      } 
   }

   public void verliereLeben()
   {
      leben--;
      meinBall.geheAufStart();
   }

   public void punkteErhöhen() {
      punkte++;
   }
}

public class Block extends Rectangle {

   //Attribute
   public String farbe;

   //Referenzattribute
   public Ball meinball;
   public Spiel meinSpiel; 

   //Konstruktor
   public Block(String _farbe, int x, int y, Ball _meinball, Spiel _meinSpiel)
  	{	
      super(x, y, 60, 30);
      farbe = _farbe;
      setFillColor(farbe);
      setBorderWidth(4); 
      setBorderColor("gray");
      meinball = _meinball;
      meinSpiel = _meinSpiel; 
   }

   //Methoden
   public void act()
   {
      if(collidesWith(meinball))
      {
         meinball.abprallenY();
         meinSpiel.punkteErhöhen(); 
         destroy(); 
      }
   } 
}

public class Schlaeger extends Rectangle {

   //Attribute
   String farbe;
   int groesse;
   int geschwindigkeit = 10; 
   Spiel meinSpiel;


   //Konstruktor
   Schlaeger(String _farbe, int _groesse, Spiel _meinSpiel) {
      super(300, 480, _groesse, 20);
      farbe = _farbe;
      groesse = _groesse;
      setFillColor(_farbe);
      meinSpiel = _meinSpiel;
   }

   //Methoden
   public void act() { 
      if(isKeyDown("a")) {
         bewegeNachLinks(); 
      } 
      if(isKeyDown("d")) {
         bewegeNachRechts();
      }
   }

   public void bewegeNachRechts()
   {
      move(geschwindigkeit, 0);
   }

   public void bewegeNachLinks()
   {
      move(-geschwindigkeit, 0);
   }

   //Getter und Settermethoden
   public String gibFarbe() {
      return farbe;
   }

   public void setzeFarbe(String _farbe)
   {
      farbe = _farbe;
      setFillColor(farbe);
   }

   public void setzeGröße(int _groesse) 
   {
      if(groesse > 40)
      {
         groesse = _groesse;
         setWidth(groesse);
      }
   }


}
